/* Token Radar, radar-2 theme. A dark navy masthead on warm paper, one amber accent, tabular
   numerals everywhere a dollar is shown. No external assets: every byte is local. */
:root {
  --navy: #0f1e2e;
  --navy-soft: #1b3049;
  --canvas: #f6f3ec;
  --surface: #fffdf8;
  --ink: #17222e;
  --muted: #5d6b78;
  --border: #d9d2c2;
  --accent: #b45309;
  --accent-soft: #fdf0dc;
  --positive: #177245;
  --negative: #b3261e;
  --radius: 10px;
  --radius-lg: 16px;
  --font-body: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-num: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --s1: 4px;
  --s2: 8px;
  --s3: 12px;
  --s4: 16px;
  --s5: 24px;
  --s6: 32px;
  --s7: 48px;
}

* { box-sizing: border-box; }
html { color-scheme: light; }
body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font: 400 15px/1.55 var(--font-body);
}
h1, h2, h3 { margin: 0; letter-spacing: -0.02em; }
h1 { font-size: 32px; line-height: 1.12; font-weight: 700; }
h2 { font-size: 20px; line-height: 1.25; font-weight: 700; }
h3 { font-size: 15px; line-height: 1.3; font-weight: 700; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.skip { position: absolute; left: -9999px; top: 0; padding: var(--s2) var(--s4); background: var(--surface); border: 1px solid var(--border); z-index: 30; }
.skip:focus { left: var(--s4); top: var(--s4); }

.shell { max-width: 1360px; margin: 0 auto; padding: 0 var(--s6) var(--s7); }
.masthead {
  background: var(--navy); color: #f3efe6; margin: 0 calc(-1 * var(--s6));
  padding: var(--s5) var(--s6) var(--s6);
}
.masthead .row { display: flex; align-items: baseline; justify-content: space-between; gap: var(--s5); flex-wrap: wrap; }
.brand { display: flex; align-items: center; gap: var(--s3); font-weight: 700; letter-spacing: 0.14em; font-size: 13px; text-transform: uppercase; }
.brand .dot { width: 14px; height: 14px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 4px rgba(180, 83, 9, 0.35); flex: none; }
.masthead .meta { display: flex; gap: var(--s4); flex-wrap: wrap; color: #b9c4d0; font-size: 13px; }
.masthead .meta b { color: #f3efe6; font-weight: 600; }

.lede { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(300px, 0.7fr); gap: var(--s6); padding: var(--s6) 0 var(--s5); }
.lede .kicker { color: var(--accent); font-weight: 700; font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; margin-bottom: var(--s2); }
.lede p { color: var(--muted); max-width: 64ch; margin-top: var(--s2); }
.facts { display: grid; gap: var(--s2); align-content: start; border-left: 2px solid var(--border); padding-left: var(--s5); }
.fact { display: flex; align-items: baseline; justify-content: space-between; gap: var(--s3); }
.fact b { font-family: var(--font-num); font-size: 16px; font-weight: 600; }
.fact span { color: var(--muted); font-size: 13px; }

.spotlight { padding-bottom: var(--s5); }
.spotlight h2 { margin-bottom: var(--s3); }
.cards { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: var(--s3); }
.card {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg);
  padding: var(--s4); text-align: left; display: grid; gap: var(--s1); min-height: 132px;
}
.card:hover { border-color: var(--accent); }
.card .rank { font-family: var(--font-num); font-size: 12px; color: var(--accent); font-weight: 700; }
.card b { font-size: 15px; line-height: 1.25; }
.card .sub { color: var(--muted); font-size: 12px; }
.card .value { font-family: var(--font-num); font-size: 15px; font-weight: 700; margin-top: auto; }
.card .tvl { font-family: var(--font-num); font-size: 12px; color: var(--muted); }

.controls { display: flex; flex-wrap: wrap; align-items: end; gap: var(--s3); padding: var(--s4) 0; border-top: 2px solid var(--ink); }
.field { display: grid; gap: var(--s1); }
.field label { color: var(--muted); font-size: 12px; font-weight: 600; }
.field input, .field select {
  min-height: 38px; padding: 0 var(--s3); border: 1px solid var(--border); border-radius: var(--radius);
  background: var(--surface); min-width: 170px;
}
.field input { min-width: 260px; }
.tabs { display: flex; gap: var(--s1); padding: 3px; border: 1px solid var(--border); border-radius: var(--radius); background: var(--surface); }
.tabs button { min-height: 32px; padding: 0 var(--s3); border: 0; border-radius: 7px; background: transparent; color: var(--muted); font-weight: 600; }
.tabs button[aria-pressed="true"] { background: var(--navy); color: #f3efe6; }
.count { margin-left: auto; color: var(--muted); font-size: 13px; align-self: center; }

.panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); overflow: hidden; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
th, td { padding: var(--s3); border-bottom: 1px solid var(--border); text-align: left; vertical-align: middle; }
thead th { position: sticky; top: 0; background: var(--surface); color: var(--muted); font-size: 12px; font-weight: 600; white-space: nowrap; z-index: 2; }
th button { display: inline-flex; align-items: center; gap: var(--s1); border: 0; background: none; padding: 0; color: inherit; font: inherit; font-weight: 600; }
th button:hover { color: var(--ink); }
tbody tr { cursor: pointer; }
tbody tr:hover { background: var(--accent-soft); }
tbody tr[data-selected="true"] { background: var(--accent-soft); }
.num { font-family: var(--font-num); font-variant-numeric: tabular-nums; white-space: nowrap; }
.name { display: grid; gap: 2px; }
.name b { font-weight: 650; }
.sub { color: var(--muted); font-size: 12px; }
.pos { color: var(--positive); }
.neg { color: var(--negative); }
.bar { width: 110px; height: 7px; border-radius: 4px; background: #e9e2d2; overflow: hidden; }
.bar i { display: block; height: 100%; background: var(--accent); }
.implied { display: flex; align-items: center; gap: var(--s2); }
.tag { display: inline-block; font-family: var(--font-num); font-size: 11px; padding: 1px 6px; border-radius: 20px; background: var(--accent-soft); color: var(--accent); white-space: nowrap; }
.tag.live { background: #e2efe6; color: var(--positive); }
.status { display: inline-flex; align-items: center; gap: 6px; color: var(--muted); font-size: 12px; white-space: nowrap; }
.status::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--accent); }

.pager { display: flex; align-items: center; gap: var(--s2); padding: var(--s3) var(--s4); border-top: 1px solid var(--border); }
.pager .spacer { flex: 1; }
.pager button { min-height: 34px; padding: 0 var(--s3); border: 1px solid var(--border); border-radius: var(--radius); background: var(--surface); font-weight: 600; }
.pager button[disabled] { opacity: 0.45; cursor: default; }
.pager .page-label { font-family: var(--font-num); font-size: 13px; color: var(--muted); }

.model { margin-top: var(--s4); padding: var(--s5); display: grid; gap: var(--s3); }
.formula { font-family: var(--font-num); font-size: 13px; line-height: 1.8; color: var(--muted); background: var(--canvas); border-radius: var(--radius); padding: var(--s3) var(--s4); overflow-wrap: anywhere; }
.mult-table { width: 100%; font-size: 13px; }
.mult-table th, .mult-table td { padding: var(--s2) var(--s3); }
.mult-table thead th { position: static; }
.empty { padding: var(--s7) var(--s5); text-align: center; display: grid; gap: var(--s3); justify-items: center; }
.empty p { color: var(--muted); }
.button { min-height: 38px; padding: 0 var(--s4); border: 1px solid var(--border); border-radius: var(--radius); background: var(--surface); font-weight: 600; }
.button.primary { background: var(--accent); border-color: var(--accent); color: #fff; }

.detail {
  position: fixed; top: 0; right: 0; bottom: 0; width: min(560px, 94vw); z-index: 10;
  background: var(--surface); border-left: 1px solid var(--border); padding: var(--s5);
  overflow-y: auto; margin: 0 0 0 auto; max-height: 100%;
}
.detail::backdrop { background: rgba(15, 30, 46, 0.35); }
.detail-head { display: flex; align-items: start; justify-content: space-between; gap: var(--s4); }
.detail-head > div { min-width: 0; }
.detail-head .sub { overflow-wrap: anywhere; }
.close { flex: none; min-height: 34px; padding: 0 var(--s3); white-space: nowrap; border: 1px solid var(--border); border-radius: var(--radius); background: var(--surface); font-weight: 600; }
.detail h2 { margin-top: var(--s1); }
.detail .sub { margin-top: var(--s1); }
.detail-section { margin-top: var(--s5); padding-top: var(--s4); border-top: 1px solid var(--border); }
.detail-section h3 { margin-bottom: var(--s2); }
.breakdown { display: grid; gap: var(--s2); font-family: var(--font-num); font-size: 13px; }
.breakdown div { display: flex; justify-content: space-between; gap: var(--s3); }
.breakdown span { color: var(--muted); }
.breakdown .total { border-top: 1px solid var(--border); padding-top: var(--s2); font-weight: 700; }
.breakdown .total span { color: var(--ink); }
.steps { margin: 0; padding-left: var(--s5); display: grid; gap: var(--s3); }
.steps li { padding-left: var(--s1); }
.steps b { display: block; font-weight: 550; }
.cost { color: var(--muted); font-size: 12px; font-family: var(--font-num); }

@media (max-width: 1100px) { .cards { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@media (max-width: 900px) {
  .shell { padding: 0 var(--s4) var(--s7); }
  .masthead { margin: 0 calc(-1 * var(--s4)); padding: var(--s4) var(--s4) var(--s5); }
  .lede { grid-template-columns: 1fr; gap: var(--s4); }
  .facts { border-left: 0; border-top: 2px solid var(--border); padding-left: 0; padding-top: var(--s4); }
  .cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .field input { min-width: 0; width: 100%; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
}
